const VALID_VARIANTS = new Set(['primary', 'secondary']);
const VALID_STATES = new Set(['default', 'hover', 'focus', 'populated']);

function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/\"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export default {
  async main(input = {}) {
    const {
      label = 'Search',
      placeholder = 'Search',
      value = '',
      variant = 'primary',
      state = 'default',
      showClear = true,
      searchIconLabel = 'Search',
    } = input;

    const safeVariant = VALID_VARIANTS.has(variant) ? variant : 'primary';
    const inferredState = value ? 'populated' : 'default';
    const safeState = VALID_STATES.has(state) ? state : inferredState;
    const resolvedState = value && state === 'default' ? 'populated' : safeState;

    const hasValue = Boolean(value);
    const showClearControl = Boolean(showClear && hasValue && resolvedState === 'populated');

    const wrapperClass = `search-field search-field--${safeVariant} search-field--${resolvedState}`;

    return /*html*/`
<div class="${wrapperClass}" data-variant="${safeVariant}" data-state="${resolvedState}">
  <label class="search-field__label">${esc(label)}</label>
  <div class="search-field__control" role="group" aria-label="${esc(label)}">
    <input
      class="search-field__input"
      type="search"
      name="q"
      value="${esc(value)}"
      placeholder="${esc(placeholder)}"
      autocomplete="off"
    />
    ${showClearControl ? `<button class="search-field__clear" type="button" aria-label="Clear search text">&#10005;</button>` : ''}
    <button class="search-field__search" type="button" aria-label="${esc(searchIconLabel)}">
      <span class="search-field__search-icon" aria-hidden="true">&#128269;</span>
      <span class="search-field__sr-only">${esc(searchIconLabel)}</span>
    </button>
  </div>
</div>
`;
  },
};
